package com.gymmind.membership.application; import com.gymmind.audit.application.AuditRecorder; import com.gymmind.audit.domain.*; import com.gymmind.iam.domain.model.RoleCode; import com.gymmind.membership.domain.model.Order; import com.gymmind.membership.domain.repository.OrderRepository; import com.gymmind.shared.error.*; import com.gymmind.shared.security.CurrentActor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.Map; @Service public class DefaultOrderService{private final OrderRepository orders;private final AuditRecorder audit;public DefaultOrderService(OrderRepository o,AuditRecorder a){orders=o;audit=a;}@Transactional public OrderView create(CurrentActor a,CreateOrderCommand c){if(a==null||a.tenantId()==null||!a.roles().contains(RoleCode.GYM_ADMIN)||!a.hasPermission("order:write"))throw new BusinessException(ErrorCode.FORBIDDEN);if(c==null||c.tenantId()!=null&&!a.tenantId().equals(c.tenantId()))throw new BusinessException(ErrorCode.FORBIDDEN);Order o=orders.save(Order.create(a.tenantId(),c.memberId(),c.total(),c.currency()));audit.record(new AuditEvent("ORDER_CREATED","ORDER",o.getId(),AuditResult.SUCCESS,"order-service",Map.of()));return OrderView.from(o);}}
